void display(const free throws & ft)
{
    using std::cout;
    cout << "Name: " << ft.name << '\n';
    cout << "_Made: " << ft.made << '\t';
    cout << "Attempts: " << ft.attempts << '\t';
    cout << "Percent: " << ft.percent << '\n';
